export interface TableFilterData {
  /**
   * @zh 筛选数据选项的内容
   * @en Filter the content of the data option
   */
  text: string | RenderFunction
  /**
   * @zh 筛选数据选项的值
   * @en Filter the value of the data option
   */
  value: string
}

export interface TableOperationColumn {
  name: OperationName | string
  title?: string | RenderFunction
  width?: number
  fixed?: boolean
  render?: (record: TableData) => VNodeChild
  isLastLeftFixed?: boolean
  /** auto 布局下渲染后测量回写的真实宽度，用于冻结偏移计算 */
  _realWidth?: number
}

export interface TableComponents {
  operations: (operations: {
    dragHandle?: TableOperationColumn
    expand?: TableOperationColumn
    selection?: TableOperationColumn
  }) => TableOperationColumn[]
}

export type TypedTableRowKey<Row extends TableData> = {
  [Key in Extract<keyof Row, string>]-?: NonNullable<Row[Key]> extends BaseType ? Key : never
}[Extract<keyof Row, string>]

export type TypedTableSortable<Row extends TableData> = Omit<TableSortable, 'sorter'> & {
  sorter?: boolean | ((a: Row, b: Row, extra: { dataIndex: TableDataPath<Row>; direction: 'ascend' | 'descend' }) => number)
}

export type TypedTableFilterable<Row extends TableData> = Omit<TableFilterable, 'filter'> & {
  filter: (filteredValue: string[], record: Row) => boolean
}

export type TypedTableExpandable<Row extends TableData> = Omit<TableExpandable, 'expandedRowRender' | 'icon'> & {
  expandedRowRender?: (record: Row) => VNodeChild
  icon?: (expanded: boolean, record: Row) => VNodeChild
}

export function defineTableConfig<Row extends TableData>(config: TypedTableConfig<Row>): TableProps {
  return config as unknown as TableProps
}

export function markTableExtraColumn<T extends object>(column: T): T {
  return Object.assign(column, { [TABLE_EXTRA_COLUMN_MARKER]: true });
}

export function isTableExtraColumn(column: object | undefined): boolean {
  return Boolean((column as { [TABLE_EXTRA_COLUMN_MARKER]?: boolean } | undefined)?.[TABLE_EXTRA_COLUMN_MARKER]);
}

export function setExtraColumnLayoutKey(column: object, key: string): void {
  Object.assign(column, { [TABLE_EXTRA_COLUMN_LAYOUT_KEY]: key });
}

export function getColumnLayoutKey(column: { dataIndex?: string }): string | undefined {
  return (column as { [TABLE_EXTRA_COLUMN_LAYOUT_KEY]?: string })[TABLE_EXTRA_COLUMN_LAYOUT_KEY] ?? column.dataIndex;
}

export type TableExtraColumnConfig = {
  /** 列宽。未传时默认 28px */
  width?: number;
  fixed?: "left" | "right";
  align?: "left" | "center" | "right";
  dataIndex?: string;
};

export function resolveExtraColumnConfig(
  extraColumn?: boolean | TableExtraColumnConfig,
): {
  enabled: boolean;
  width?: number;
  fixed: "left" | "right";
  align: "left" | "center" | "right";
  dataIndex: string;
} {
  if (!extraColumn) {
    return {
      enabled: false,
      fixed: "right",
      align: "center",
      dataIndex: TABLE_EXTRA_COLUMN_KEY,
    };
  }
  const conf = extraColumn === true ? {} : extraColumn;
  return {
    enabled: true,
    width: conf.width,
    fixed: conf.fixed ?? "right",
    align: conf.align ?? "center",
    dataIndex: conf.dataIndex ?? TABLE_EXTRA_COLUMN_KEY,
  };
}

export function getExtraColumnWidth(
  size?: ComponentSize | string,
  customWidth?: number,
): number {
  if (customWidth != null) return customWidth;
  return DEFAULT_EXTRA_COLUMN_WIDTH;
}
